import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// =====================================================================
// BACKGROUND — Back_Dark.png
// =====================================================================
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// =====================================================================
// SCENE 1 — Grid of abstract post tiles with scanner sweep
// =====================================================================
const SCENE1_DUR = 125;

const PostTile: React.FC<{
  row: number;
  col: number;
  index: number;
  scannerX: number;
  tileW: number;
  tileH: number;
  gap: number;
  gridLeft: number;
  gridTop: number;
}> = ({ row, col, index, scannerX, tileW, tileH, gap, gridLeft, gridTop }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const inP = staggeredSpring(frame, vfps, index, 4, 1.5, "LIQUID");
  const x = gridLeft + col * (tileW + gap);
  const y = gridTop + row * (tileH + gap);
  const tileCenter = x + tileW / 2;

  const dist = Math.abs(scannerX - tileCenter);
  const beamFalloff = Math.max(0, 1 - dist / 280);
  const highlight = beamFalloff * 0.55;

  const driftY = ambientDrift(frame, 1.2, 70 + (index % 5) * 11, `tile-${index}`);

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: tileW,
        height: tileH,
        background: `linear-gradient(135deg, rgba(255,255,255,0.04), rgba(255,255,255,0.015))`,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 22,
        overflow: "hidden",
        opacity: inP * (0.55 + highlight * 0.8),
        transform: `translateY(${interpolate(inP, [0, 1], [16, 0]) + driftY}px) scale(${interpolate(inP, [0, 1], [0.94, 1])})`,
        boxShadow:
          beamFalloff > 0.1
            ? `inset 0 0 0 1px rgba(248,102,6,${beamFalloff * 0.55}), 0 0 ${30 * beamFalloff}px rgba(248,102,6,${beamFalloff * 0.35})`
            : "none",
        padding: 18,
        display: "flex",
        flexDirection: "column",
        gap: 12,
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <div
          style={{
            width: 28,
            height: 28,
            borderRadius: 999,
            background: `rgba(255,255,255,${0.08 + highlight * 0.2})`,
          }}
        />
        <div
          style={{
            width: "55%",
            height: 8,
            borderRadius: 4,
            background: `rgba(255,255,255,${0.1 + highlight * 0.3})`,
          }}
        />
      </div>
      <div
        style={{
          width: "92%",
          height: 8,
          borderRadius: 4,
          background: `rgba(255,255,255,${0.07 + highlight * 0.25})`,
        }}
      />
      <div
        style={{
          width: "78%",
          height: 8,
          borderRadius: 4,
          background: `rgba(255,255,255,${0.07 + highlight * 0.2})`,
        }}
      />
      <div style={{ flex: 1 }} />
      <div style={{ display: "flex", gap: 10 }}>
        <div
          style={{
            width: 40,
            height: 6,
            borderRadius: 3,
            background: `rgba(255,255,255,${0.08 + highlight * 0.2})`,
          }}
        />
        <div
          style={{
            width: 28,
            height: 6,
            borderRadius: 3,
            background: `rgba(248,102,6,${0.15 + highlight * 0.5})`,
          }}
        />
      </div>
    </div>
  );
};

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();

  const cols = 4;
  const rows = 3;
  const tileW = 460;
  const tileH = 360;
  const gap = 56;
  const gridW = cols * tileW + (cols - 1) * gap;
  const gridH = rows * tileH + (rows - 1) * gap;
  const gridLeft = (3840 - gridW) / 2;
  const gridTop = (2160 - gridH) / 2;

  const sweepStart = 18;
  const sweepEnd = 110;
  const sweepProgress = interpolate(frame, [sweepStart, sweepEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scannerX = interpolate(sweepProgress, [0, 1], [gridLeft - 40, gridLeft + gridW + 40]);

  const scannerOpacity = interpolate(
    frame,
    [10, 18, sweepEnd - 5, sweepEnd + 5],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill>
      <Background />
      <AbsoluteFill>
        {Array.from({ length: rows * cols }).map((_, i) => {
          const r = Math.floor(i / cols);
          const c = i % cols;
          return (
            <PostTile
              key={i}
              row={r}
              col={c}
              index={i}
              scannerX={scannerX}
              tileW={tileW}
              tileH={tileH}
              gap={gap}
              gridLeft={gridLeft}
              gridTop={gridTop}
            />
          );
        })}
      </AbsoluteFill>

      {/* Scanner beam */}
      <div
        style={{
          position: "absolute",
          left: scannerX,
          top: gridTop - 40,
          width: 3,
          height: gridH + 80,
          background: `linear-gradient(180deg, transparent, ${COLORS.orange}, transparent)`,
          opacity: scannerOpacity,
          boxShadow: `0 0 40px ${COLORS.orange}, 0 0 100px ${COLORS.orange}`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: scannerX - 160,
          top: gridTop - 40,
          width: 160,
          height: gridH + 80,
          background: `linear-gradient(90deg, transparent, rgba(248,102,6,0.18))`,
          opacity: scannerOpacity * 0.8,
          filter: "blur(8px)",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: scannerX - 40,
          top: gridTop - 110,
          width: 80,
          height: 80,
          opacity: scannerOpacity,
          transform: `translateY(${ambientDrift(frame, 4, 22, "scanner-bob")}px)`,
        }}
      >
        <svg viewBox="0 0 80 80" width={80} height={80}>
          <circle cx={32} cy={32} r={20} fill="none" stroke={COLORS.orange} strokeWidth={4} />
          <line x1={48} y1={48} x2={68} y2={68} stroke={COLORS.orange} strokeWidth={5} strokeLinecap="round" />
          <circle cx={32} cy={32} r={20} fill={COLORS.orange} opacity={0.12} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

