const FloatingGlyph: React.FC<{
  x: number;
  y: number;
  delay: number;
  children: React.ReactNode;
  seed: string;
  size: number;
}> = ({ x, y, delay, children, seed, size }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const inP = springIn(frame, vfps, delay, "GENTLE");
  const driftX = ambientDrift(frame, 14, 90, `${seed}-x`);
  const driftY = ambientDrift(frame, 18, 110, `${seed}-y`);
  const pulse = 0.85 + 0.15 * Math.sin((frame + delay * 2) / 18);

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: size,
        height: size,
        transform: `translate(-50%, -50%) translate(${driftX}px, ${driftY}px) scale(${interpolate(inP, [0, 1], [0.5, pulse])})`,
        opacity: inP * 0.7,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: `rgba(248,102,6,0.05)`,
        border: `1px solid rgba(248,102,6,0.3)`,
        borderRadius: 999,
      }}
    >
      {children}
    </div>
  );
};

