const SCENE3_DUR = 250;

const PulsingGlyph: React.FC<{
  x: number;
  y: number;
  highlightFrame: number;
  totalFrames: number;
  children: React.ReactNode;
  seed: string;
  size: number;
}> = ({ x, y, highlightFrame, children, seed, size }) => {
  const frame = useCurrentFrame();
  const driftX = ambientDrift(frame, 16, 95, `${seed}-x`);
  const driftY = ambientDrift(frame, 20, 115, `${seed}-y`);

  const highlight = interpolate(
    frame,
    [highlightFrame - 5, highlightFrame, highlightFrame + 35, highlightFrame + 45],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const scaleBase = 1 + 0.06 * Math.sin(frame / 16);
  const scale = scaleBase + highlight * 0.18;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: size,
        height: size,
        transform: `translate(-50%, -50%) translate(${driftX}px, ${driftY}px) scale(${scale})`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: `rgba(248,102,6,${0.06 + highlight * 0.18})`,
        border: `1.5px solid rgba(248,102,6,${0.4 + highlight * 0.5})`,
        borderRadius: 999,
        boxShadow:
          highlight > 0 ? `0 0 ${60 * highlight}px rgba(248,102,6,${highlight * 0.6})` : "none",
        opacity: 0.8 + highlight * 0.2,
      }}
    >
      {children}
    </div>
  );
};

