          <circle cx={80} cy={20} r={14} fill="rgba(255,255,255,0.06)" stroke={COLORS.border} strokeWidth={1.5} />
          <circle cx={108} cy={20} r={10} fill="rgba(248,102,6,0.1)" stroke={COLORS.orange} strokeWidth={1.5} opacity={0.6} />
        </svg>
      ),
    },
    {
      id: "hashtags",
      label: "Hashtags",
      x: centerX + 1100,
      y: centerY + 580,
      delay: 42,
      icon: (
        <svg viewBox="0 0 24 24" width={90} height={90}>
          <line x1={9} y1={3} x2={7} y2={21} stroke={COLORS.orange} strokeWidth={2} strokeLinecap="round" />
          <line x1={17} y1={3} x2={15} y2={21} stroke={COLORS.orange} strokeWidth={2} strokeLinecap="round" />
          <line x1={3} y1={9} x2={21} y2={9} stroke={COLORS.orange} strokeWidth={2} strokeLinecap="round" />
          <line x1={3} y1={15} x2={21} y2={15} stroke={COLORS.orange} strokeWidth={2} strokeLinecap="round" />
        </svg>
      ),
      badge: (
        <svg viewBox="0 0 120 40" width={180} height={60}>
          <rect x={5} y={20} width={14} height={16} rx={2} fill={COLORS.orange} opacity={0.4} />
          <rect x={24} y={12} width={14} height={24} rx={2} fill={COLORS.orange} opacity={0.6} />
          <rect x={43} y={4} width={14} height={32} rx={2} fill={COLORS.orange} opacity={0.85} />
          <rect x={62} y={18} width={14} height={18} rx={2} fill={COLORS.orange} opacity={0.5} />
          <rect x={81} y={24} width={14} height={12} rx={2} fill={COLORS.orange} opacity={0.35} />
          <rect x={100} y={14} width={14} height={22} rx={2} fill={COLORS.orange} opacity={0.55} />
        </svg>
      ),
    },
  ];

  const nodePulse = 1 + 0.03 * Math.sin(frame / 18);

  return (
    <AbsoluteFill>
      <Background />
      {/* SVG connection lines + flowing dots */}
      <svg
        viewBox="0 0 3840 2160"
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
        }}
      >
        {destinations.map((d) => {
          const lineP = springIn(frame, vfps, d.delay, "SNAPPY");
          const startX = centerX;
          const startY = centerY + 80;
          const endX = d.x;
          const endY = d.y - 120;
          const curX = startX + (endX - startX) * 0.5;
          const curY = startY + 120;
          const path = `M ${startX} ${startY} Q ${curX} ${curY} ${endX} ${endY}`;

          const pathLen = 1200;
          const dashOffset = interpolate(lineP, [0, 1], [pathLen, 0]);

          const flowProgress = ((frame - (d.delay + 18)) / 50) % 1;
          const dotVisible = frame > d.delay + 18 ? 1 : 0;

          return (
            <g key={d.id}>
              <path
                d={path}
                stroke={COLORS.orange}
                strokeWidth={3}
                fill="none"
                strokeLinecap="round"
                strokeDasharray={pathLen}
                strokeDashoffset={dashOffset}
                opacity={lineP * 0.85}
                style={{ filter: `drop-shadow(0 0 8px ${COLORS.orange})` }}
              />
              {flowProgress >= 0 && flowProgress <= 1 && (
                <circle
                  r={8}
                  fill={COLORS.orange}
                  opacity={dotVisible * 0.95}
                  style={{ filter: `drop-shadow(0 0 12px ${COLORS.orange})` }}
                >
                  <animateMotion dur="2s" repeatCount="indefinite" path={path} />
                </circle>
              )}
            </g>
          );
        })}
      </svg>

      {/* Search node at center */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: centerY,
          transform: `translate(-50%, -50%) scale(${nodePulse})`,
        }}
      >
        <div
          style={{
            width: 240,
            height: 240,
            borderRadius: 999,
            background: `radial-gradient(circle, rgba(248,102,6,0.2), rgba(248,102,6,0.03) 70%)`,
            border: `2px solid ${COLORS.orange}`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: `0 0 80px rgba(248,102,6,0.4)`,
          }}
        >
          <svg viewBox="0 0 24 24" width={100} height={100}>
            <circle cx={11} cy={11} r={7} fill="none" stroke={COLORS.orange} strokeWidth={2} />
            <line x1={16.5} y1={16.5} x2={21} y2={21} stroke={COLORS.orange} strokeWidth={2.5} strokeLinecap="round" />
          </svg>
        </div>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "calc(100% + 28px)",
            transform: "translateX(-50%)",
            fontFamily: "Inter, sans-serif",
            fontWeight: 600,
            fontSize: 36,
            color: COLORS.text,
            letterSpacing: "0.12em",
            textTransform: "uppercase",
            whiteSpace: "nowrap",
          }}
        >
          Search
        </div>
      </div>

      {/* Destination nodes */}
      {destinations.map((d) => {
        const dInP = springIn(frame, vfps, d.delay + 14, "ELASTIC");
        const driftY = ambientDrift(frame, 4, 90, `dest-${d.id}`);
        return (
          <div
            key={d.id}
            style={{
              position: "absolute",
              left: d.x,
              top: d.y,
              transform: `translate(-50%, -50%) translateY(${driftY}px) scale(${dInP})`,
              opacity: dInP,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 24,
            }}
          >
            <div
              style={{
                width: 200,
                height: 200,
                borderRadius: 999,
                background: COLORS.card,
                border: `1.5px solid ${COLORS.orange}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: `0 0 50px rgba(248,102,6,0.25)`,
              }}
            >
              {d.icon}
            </div>
            <div
              style={{
                background: COLORS.card,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 14,
                padding: 14,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {d.badge}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// =====================================================================
// MAIN COMPOSITION — no opening/closing black, no fades to black
// =====================================================================

export const durationInFrames =
  (SCENE1_DUR + TRANSITION) +
  (SCENE2_DUR + TRANSITION) +
  (SCENE3_DUR + TRANSITION) +
  SCENE4_DUR -
  3 * TRANSITION;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE1_DUR + TRANSITION}>
        <Scene1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE2_DUR + TRANSITION}>
        <Scene2 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE3_DUR + TRANSITION}>
        <Scene3 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE4_DUR}>
        <Scene4 />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
